import{_ as e,c as r,o as a,a1 as t}from"./chunks/framework.DKHw8SZo.js";const m=JSON.parse('{"title":"Teknisk orientering om webbens protokoll (HTTP, HTTPS), IP-adresser, DNS och säkerhet.","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/3-web/how-work-web.md","filePath":"web1/3-web/how-work-web.md"}'),n={name:"web1/3-web/how-work-web.md"},s=t('<h1 id="teknisk-orientering-om-webbens-protokoll-http-https-ip-adresser-dns-och-sakerhet" tabindex="-1">Teknisk orientering om webbens protokoll (HTTP, HTTPS), IP-adresser, DNS och säkerhet. <a class="header-anchor" href="#teknisk-orientering-om-webbens-protokoll-http-https-ip-adresser-dns-och-sakerhet" aria-label="Permalink to &quot;Teknisk orientering om webbens protokoll (HTTP, HTTPS), IP-adresser, DNS och säkerhet.&quot;">​</a></h1><p>När vi använder internet varje dag, till exempel för att besöka webbsidor, titta på videor eller skicka meddelanden, sker en massa tekniska processer i bakgrunden. För att allt ska fungera smidigt och säkert används olika protokoll som styr hur information skickas mellan datorer och servrar.</p><p>I denna genomgång kommer vi att titta på fyra viktiga delar av internet:</p><ul><li><span class="f">Webbens protokoll (HTTP och HTTPS)</span> – Hur webbsidor skickas och hämtas.</li><li><span class="f">IP-adresser</span> – Hur enheter identifieras på nätverket.</li><li><span class="f">DNS</span> – Hur domännamn (som google.com) kopplas till rätt server.</li><li><span class="f">Webbens säkerhet</span> – Hur vi skyddar information från hackare och andra hot.</li></ul><p>Genom att förstå dessa grundläggande teknologier får du en bättre inblick i hur webben fungerar, hur vi kan bygga säkra webbplatser och hur vi skyddar oss på internet.</p><h2 id="_1-webbens-protokoll-http-och-https" tabindex="-1">1. Webbens protokoll: HTTP och HTTPS <a class="header-anchor" href="#_1-webbens-protokoll-http-och-https" aria-label="Permalink to &quot;1. Webbens protokoll: HTTP och HTTPS&quot;">​</a></h2><p>När du surfar på internet används olika protokoll för att skicka och ta emot information. De två viktigaste är HTTP och HTTPS.</p><h3 id="http-hypertext-transfer-protocol" tabindex="-1">HTTP (HyperText Transfer Protocol) <a class="header-anchor" href="#http-hypertext-transfer-protocol" aria-label="Permalink to &quot;HTTP (HyperText Transfer Protocol)&quot;">​</a></h3><ul><li>HTTP är ett protokoll som används för att överföra webbsidor mellan en webbserver och en webbläsare.</li><li>När du skriver in en webbadress (t.ex. www.google.com) skickas en HTTP-förfrågan till webbservern.</li><li>Webbservern svarar med en HTTP-svar, som innehåller webbsidan du vill se.</li></ul><h3 id="https-hypertext-transfer-protocol-secure" tabindex="-1">HTTPS (HyperText Transfer Protocol Secure) <a class="header-anchor" href="#https-hypertext-transfer-protocol-secure" aria-label="Permalink to &quot;HTTPS (HyperText Transfer Protocol Secure)&quot;">​</a></h3><ul><li>HTTPS är en säkrare version av HTTP.</li><li>Den använder SSL/TLS-kryptering för att skydda datan som skickas mellan din webbläsare och webbservern.</li><li>HTTPS används på sidor där säkerhet är viktig, t.ex. vid inloggning eller betalning online.</li></ul><h3 id="skillnaden-mellan-http-och-https" tabindex="-1">Skillnaden mellan HTTP och HTTPS <a class="header-anchor" href="#skillnaden-mellan-http-och-https" aria-label="Permalink to &quot;Skillnaden mellan HTTP och HTTPS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Protokoll</th><th>Säkerhet</th><th>Användning</th></tr></thead><tbody><tr><td>HTTP</td><td>Ingen kryptering</td><td>Vanliga webbsidor (ej säkra)</td></tr><tr><td>HTTPS</td><td>Krypterad dataöverföring</td><td>Banktjänster, e-handel, inloggningar</td></tr></tbody></table><br><h2 id="_2-ip-adresser-internet-protocol-address" tabindex="-1">2. IP-adresser (Internet Protocol Address) <a class="header-anchor" href="#_2-ip-adresser-internet-protocol-address" aria-label="Permalink to &quot;2. IP-adresser (Internet Protocol Address)&quot;">​</a></h2><p>Alla enheter som är anslutna till internet har en unik IP-adress. Det är en adress som används för att identifiera datorer och servrar på nätverket.</p><h3 id="tva-typer-av-ip-adresser" tabindex="-1">Två typer av IP-adresser <a class="header-anchor" href="#tva-typer-av-ip-adresser" aria-label="Permalink to &quot;Två typer av IP-adresser&quot;">​</a></h3><ol><li><p>IPv4 (Internet Protocol version 4)</p><ul><li>Består av fyra nummer mellan 0 och 255, t.ex. 192.168.1.1.</li><li>Begränsat antal adresser (ca 4 miljarder).</li></ul></li><li><p>IPv6 (Internet Protocol version 6)</p><ul><li>Har en längre adress, t.ex. 2001:0db8:85a3:0000:0000:8a2e:0370:7334.</li><li>Kan hantera många fler enheter än IPv4.</li></ul></li></ol><h3 id="publik-och-privat-ip-adress" tabindex="-1">Publik och privat IP-adress <a class="header-anchor" href="#publik-och-privat-ip-adress" aria-label="Permalink to &quot;Publik och privat IP-adress&quot;">​</a></h3><ul><li>Publik IP-adress – Tilldelas av din internetleverantör och används för att identifiera din enhet på internet.</li><li>Privat IP-adress – Används inom lokala nätverk (t.ex. hemma eller på skolan) och börjar ofta med 192.168.x.x.</li></ul><br><h2 id="_3-dns-domain-name-system" tabindex="-1">3. DNS (Domain Name System) <a class="header-anchor" href="#_3-dns-domain-name-system" aria-label="Permalink to &quot;3. DNS (Domain Name System)&quot;">​</a></h2><p>Eftersom IP-adresser är svåra att komma ihåg används DNS för att koppla domännamn (t.ex. www.google.com) till rätt IP-adress.</p><h3 id="hur-fungerar-dns" tabindex="-1">Hur fungerar DNS? <a class="header-anchor" href="#hur-fungerar-dns" aria-label="Permalink to &quot;Hur fungerar DNS?&quot;">​</a></h3><ol><li>Du skriver in www.google.com i webbläsaren.</li><li>Din dator skickar en förfrågan till en DNS-server.</li><li>DNS-servern letar upp rätt IP-adress för www.google.com.</li><li>Webbläsaren ansluter till IP-adressen och laddar webbsidan.</li></ol><h3 id="exempel-pa-dns-servrar" tabindex="-1">Exempel på DNS-servrar <a class="header-anchor" href="#exempel-pa-dns-servrar" aria-label="Permalink to &quot;Exempel på DNS-servrar&quot;">​</a></h3><ul><li>Google DNS: 8.8.8.8 och 8.8.4.4</li><li>Cloudflare DNS: 1.1.1.1</li><li>OpenDNS: 208.67.222.222 och 208.67.220.220</li></ul><br><h2 id="_4-webbens-sakerhet" tabindex="-1">4. Webbens säkerhet <a class="header-anchor" href="#_4-webbens-sakerhet" aria-label="Permalink to &quot;4. Webbens säkerhet&quot;">​</a></h2><p>ftersom internet är öppet och används av miljarder människor finns det också risker. Hackare kan försöka stjäla information, sprida virus eller lura användare. Därför finns det flera säkerhetslösningar, till exempel:</p><ul><li>HTTPS – Krypterar data så att ingen kan läsa den under överföringen.</li><li>SSL/TLS-certifikat – Används av webbplatser för att bevisa att de är säkra.</li><li>Brandväggar – Skyddar nätverk och datorer från skadliga attacker.</li><li>Tvåfaktorsautentisering (2FA) – Ett extra säkerhetslager vid inloggning.</li></ul><br><h2 id="sammanfattning" tabindex="-1">Sammanfattning <a class="header-anchor" href="#sammanfattning" aria-label="Permalink to &quot;Sammanfattning&quot;">​</a></h2><p>✅ HTTP används för att ladda webbsidor, medan HTTPS är en säker version av HTTP.<br> ✅ IP-adresser identifierar enheter på internet, och det finns IPv4 och IPv6.<br> ✅ DNS översätter domännamn till IP-adresser så att vi slipper komma ihåg siffror.<br> ✅ Säkerhet skyddar information från hackare och andra hot.</p><p>Detta kommer att hjälpa dig att förstå grunderna i webbens protokoll, IP-adresser. DNS, säkerhet!</p><p>😎 👊 👍</p>',36),l=[s];function o(i,d,h,p,k,b){return a(),r("div",null,l)}const u=e(n,[["render",o]]);export{m as __pageData,u as default};
